settings_json.customCss:
/* 結い庵だけの事情。
   色・余白・書体・角の丸み・写真の比率・本文の読み幅・スタッフ写真の大きさ・
   スマホでのヒーロー写真の切り抜きは「サイト全体」の設定で決まるようになった
   （2026-09-12）。ここに残すのは、この店の写真と文字数に固有のものだけ。 */

/* ヒーロー。写真を主役にして、文字は左に置く。写真は暗く覆わない */
.lhp-hero{ min-height:auto; padding-block:clamp(40px,6vw,72px); }
.lhp-hero-split .lhp-hero-inner{ gap:clamp(24px,4vw,64px); align-items:center; }
/* 主コピーは2行で収まる大きさに。行間は和文の字面に合わせて広め */
.lhp-hero h1{ font-size:clamp(27px,3.6vw,42px); line-height:1.65; }
/* 店名と業種は補助。主コピーの下に小さく置く */
.lhp-hero-sub{
  font-size:clamp(13px,1.5vw,15px); line-height:1.9; letter-spacing:.12em;
  color:#6b5c4e; opacity:1; margin-top:1.1em;
}
@media(max-width:768px){
  .lhp-hero h1{ font-size:26px; line-height:1.7; }
  .lhp-hero .lhp-btn-primary{ width:100%; }
  /* 中央の縦線の飾りは、左寄せの文字と合わない */
  .lhp-hero-inner::before{ display:none !important; }
  .lhp-hero{ padding-block:20px 28px; }
}

/* 料金。この店は3桁の金額が並ぶので、数字だけ少し詰める */
.lhp-price-amount{ letter-spacing:.02em; }

/* 並べた写真は、この店の枚数だと900pxで収まりがよい。
   2列の隙間は、4:5の縦位置がそろって見える程度に詰める */
.lhp-gallery{ gap:12px; max-width:900px; margin:0 auto; }

/* スタイリストの名前と肩書き。この字数だと少し広げたほうが読みやすい */
.lhp-team-name{ font-size:16px; letter-spacing:.04em; }

/* 営業時間の表は、この情報量だと420pxが読みやすい */
.lhp-hours{ max-width:420px; margin:0 auto; }
